import { test, expect } from '@playwright/test';

test.describe('Mobile Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
    await page.setViewportSize({ width: 375, height: 812 }); // Set viewport to mobile size
  });

  test('should display hamburger menu on mobile', async ({ page }) => {
    const hamburgerMenu = page.getByRole('button', { name: /menu/i });
    await expect(hamburgerMenu).toBeVisible();
  });

  test('should open the navigation menu when hamburger is clicked', async ({ page }) => {
    const hamburgerMenu = page.getByRole('button', { name: /menu/i });
    await hamburgerMenu.click();

    const navMenu = page.getByRole('navigation');
    await expect(navMenu).toBeVisible();
  });
});
